import{c as e,i as t,n,o as r,r as i,s as a,t as o}from"./app-CSY-Kgjv.js";var s=JSON.parse(`{"path":"/hardware/communication.html","title":"通讯基础","lang":"zh-CN","frontmatter":{"description":"通讯基础 频率 频率和波长是物理学中的两个重要概念。频率指的是单位时间内波的周期数，通常用赫兹（Hz）来表示。波长则是波在空间中传播一个周期所占据的距离，通常用米（m）来表示。频率和波长之间的关系可以用一个简单的公式来表示：频率等于光速除以波长。 f=c÷l er 频率特性 高频信号是指频率高于一定阈值的信号，其通常频率范围在几十千赫兹（kHz）到几百...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"通讯基础\\",\\"image\\":[\\"https://deelmind.com/imgs/hardware/hz.png\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/hardware/communication.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"通讯基础"}],["meta",{"property":"og:description","content":"通讯基础 频率 频率和波长是物理学中的两个重要概念。频率指的是单位时间内波的周期数，通常用赫兹（Hz）来表示。波长则是波在空间中传播一个周期所占据的距离，通常用米（m）来表示。频率和波长之间的关系可以用一个简单的公式来表示：频率等于光速除以波长。 f=c÷l er 频率特性 高频信号是指频率高于一定阈值的信号，其通常频率范围在几十千赫兹（kHz）到几百..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://deelmind.com/imgs/hardware/hz.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.73,"words":518},"filePathRelative":"hardware/communication.md","autoDesc":true}`),c={name:`communication.md`};function l(o,s,c,l,u,d){let f=e(`DocsAD`);return a(),i(`div`,null,[s[0]||=n(`h1`,{id:`通讯基础`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#通讯基础`},[n(`span`,null,`通讯基础`)])],-1),s[1]||=n(`h2`,{id:`频率`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#频率`},[n(`span`,null,`频率`)])],-1),s[2]||=n(`p`,null,`频率和波长是物理学中的两个重要概念。频率指的是单位时间内波的周期数，通常用赫兹（Hz）来表示。波长则是波在空间中传播一个周期所占据的距离，通常用米（m）来表示。频率和波长之间的关系可以用一个简单的公式来表示：频率等于光速除以波长。`,-1),r(f),s[3]||=t(`<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>f</mi><mo>=</mo><mi>c</mi><mo>÷</mo><mi>l</mi></mrow><annotation encoding="application/x-tex">f = c \\div l </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">÷</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span></span></span></span></span></p><p><img src="/imgs/hardware/hz.png" alt="er"></p><h2 id="频率特性" tabindex="-1"><a class="header-anchor" href="#频率特性"><span>频率特性</span></a></h2><p>高频信号是指频率高于一定阈值的信号，其通常频率范围在几十千赫兹（kHz）到几百兆赫兹（MHz）之间。高频信号的特点是波长短、传输距离短、传输速度快，常用于无线通讯、雷达、卫星通讯等领域。</p><p>低频信号则是指频率低于一定阈值的信号，其通常频率范围在几赫兹（Hz）到几十千赫兹（kHz）之间。低频信号的特点是波长长、传输距离长、传输速度慢，常用于音频信号、电力信号等领域。</p><h2 id="频段" tabindex="-1"><a class="header-anchor" href="#频段"><span>频段</span></a></h2><p>频段是指一个连续电磁波的频率范围。在无线电通信中，频段通常用于划分不同的频率资源，以便于不同的通信系统之间进行区分和协调。频段的表示方法通常是用起始频率和终止频率来表示，例如，2.4GHz 和 5GHz 就是两个常见的无线网络频段。</p><h2 id="噪声" tabindex="-1"><a class="header-anchor" href="#噪声"><span>噪声</span></a></h2><h2 id="调制解调" tabindex="-1"><a class="header-anchor" href="#调制解调"><span>调制解调</span></a></h2><p>调制与解调，是无线通信领域中常见的技术词汇。在发送端把基带信号（包含传输信息的有效信号）加载到某个载波（通常为高频的正弦或余弦波）的过程称为调制，得到的信号称为已调信号。解调是调制的逆过程，就是在接收端通过某种信号处理手段从已调信号中得到基带信号。</p><ul><li>AM</li><li>FM</li><li>CW</li><li>LSB</li><li>USB</li><li>WFM</li><li>DSB</li><li>RAW</li></ul><h2 id="fft" tabindex="-1"><a class="header-anchor" href="#fft"><span>FFT</span></a></h2><p>快速傅里叶变化</p><h2 id="滤波" tabindex="-1"><a class="header-anchor" href="#滤波"><span>滤波</span></a></h2><h2 id="采样" tabindex="-1"><a class="header-anchor" href="#采样"><span>采样</span></a></h2><h2 id="采样率" tabindex="-1"><a class="header-anchor" href="#采样率"><span>采样率</span></a></h2><h2 id="采样类型" tabindex="-1"><a class="header-anchor" href="#采样类型"><span>采样类型</span></a></h2>`,17)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};